import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Engineering","description":"Hearth engineering principles, technology stack, runtime shape, data organization, testing, and release constraints.","frontmatter":{"title":"Engineering","description":"Hearth engineering principles, technology stack, runtime shape, data organization, testing, and release constraints.","outline":[2]},"headers":[],"relativePath":"en/reference/engineering.md","filePath":"en/reference/engineering.md","lastUpdated":1794305977000}'),s={name:"en/reference/engineering.md"};function i(o,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="engineering" tabindex="-1">Engineering <a class="header-anchor" href="#engineering" aria-label="Permalink to &quot;Engineering&quot;">​</a></h1><p class="lead">The design section defines product boundaries; engineering defines how those boundaries become a runnable, verifiable, recoverable system. These choices are defaults, not dogma, but task correctness, authority, and recovery are not traded away for convenience.</p><h2 id="engineering-principles-and-runtime-shape" tabindex="-1">Engineering Principles and Runtime Shape <a class="header-anchor" href="#engineering-principles-and-runtime-shape" aria-label="Permalink to &quot;Engineering Principles and Runtime Shape&quot;">​</a></h2><ul><li><strong>Modular monolith first.</strong> Do not introduce microservices early. Keep control, tasks, execution, memory, and entrances in one deployable system, with boundaries maintained by interfaces and tests.</li><li><strong>Deliver vertical slices.</strong> Every phase includes interface, persistent state, real execution, verification, and recovery. A backend-only capability is not done.</li><li><strong>Record facts first.</strong> Task state, approvals, artifacts, and receipts are written locally before interfaces, notifications, and reports are rebuilt.</li><li><strong>One write authority per state.</strong> The early system uses one process, one writer, and a local database so two executors cannot advance the same work at once.</li><li><strong>Execution must recover.</strong> Long work saves checkpoints and execution records so it survives restarts, sleep, network loss, and executor crashes.</li><li><strong>External actions are approved.</strong> Sends, writes, deletes, publishes, and payments use preview, authorization, idempotency, and receipts; executors cannot bypass them.</li><li><strong>Adapters stay isolated.</strong> Codex, connectors, browsers, desktop operation, and isolation environments enter through one capability boundary.</li><li><strong>Local-first and portable.</strong> Personal data stays local by default; cloud services are replaceable; users can export, back up, and restore.</li><li><strong>Versions and rollback.</strong> Data structures, executors, methods, and configuration are versioned, and a failed upgrade returns to the last stable version.</li><li><strong>Observable without intrusion.</strong> Every task has a trace, cost, and failure category. The interface shows what users need; detailed records remain in a local audit view.</li></ul><table tabindex="0"><thead><tr><th>Layer</th><th>Default</th><th>Reason</th></tr></thead><tbody><tr><td>Primary language</td><td>TypeScript</td><td>Service, command line, web, and adapters share concepts and validation</td></tr><tr><td>Service runtime</td><td>Node.js 22.13+</td><td>Fits high-I/O orchestration and event delivery; document work uses built-in <code>node:sqlite</code></td></tr><tr><td>Resident service</td><td>One modular-monolith process</td><td>Reduces early operational cost and protocol drift</td></tr><tr><td>Local storage</td><td>SQLite in WAL mode</td><td>Enough for single-user, local-first, single-writer use with simple backup</td></tr><tr><td>Data validation</td><td>Versioned data structures</td><td>External input, records, and actions still need runtime validation</td></tr><tr><td>Web</td><td>React and Vite</td><td>Fits task cards, approvals, artifacts, and live state; the PWA shell and mobile navigation exist, while phone pairing, system push, and remote takeover are not accepted</td></tr><tr><td>Live updates</td><td>Server-sent event push</td><td>Simpler than a two-way persistent connection for state changes</td></tr><tr><td>Browser automation</td><td>Not built in</td><td>Web sources use <code>fetch</code> + <code>cheerio</code>; sites that need a signed-in session or interaction stay inside the executor workspace</td></tr><tr><td>Documents and data</td><td>Server-side TypeScript</td><td><code>pdfjs-dist</code>, <code>mammoth</code>, and <code>exceljs</code> extract PDF, DOCX, and XLSX in-process</td></tr><tr><td>Isolation</td><td>One workspace per task</td><td>Today isolation is the task workspace plus restricted tool permissions; containers and high-risk isolation rooms remain unfinished work in <a href="/hearth-os/en/delivery/stage-3.html">Phase 3</a></td></tr></tbody></table><p>TypeScript is the language; Node.js is the runtime. The former constrains development-time types, while the latter provides files, networking, processes, and timers. External input and persisted data still need runtime validation. The primary language does not change the real safety boundaries of isolation, approval, recovery, and authority.</p><p>The early system has one resident service writing the main database. Command line, web, mobile, and executors connect through task queues or controlled interfaces and do not write the database directly. Executors can be replaced while tasks, authority, and receipts remain in the main system. Document extraction runs inside the server process; browser workers and device agents join as controlled capabilities when needed, not as a second business protocol.</p><p>Local data should be understandable, backupable, and portable. The main record stores tasks and events. Artifacts are stored separately and verified by content. Workspaces are created and cleaned by task. Configuration stores rules and connections. Credentials contain only encrypted material or short-lived references. Logs and backups are kept separately. Sensitive directories use minimal permissions, backups are encrypted, and device sync sends only necessary state and artifact references.</p><h2 id="data-testing-and-release" tabindex="-1">Data, Testing, and Release <a class="header-anchor" href="#data-testing-and-release" aria-label="Permalink to &quot;Data, Testing, and Release&quot;">​</a></h2><p>The repository is organized by entrances, core capability, executors, tests, and evaluation rather than by page or arbitrary team boundary.</p><table tabindex="0"><thead><tr><th>Area</th><th>Responsibility</th></tr></thead><tbody><tr><td>Service, web, command line, device node</td><td>Entrances, task cards, approvals, artifacts, notifications, and takeover</td></tr><tr><td>Core state</td><td>Tasks, work units, execution records, checkpoints, recovery, and failure classes</td></tr><tr><td>Fact records</td><td>Append-only records, projections, migrations, replay, and audit</td></tr><tr><td>Control and authority</td><td>Triggers, autonomy levels, authorization scope, risk, and anomaly stops</td></tr><tr><td>Context and cost</td><td>Minimal context, model selection, budget, cache, and cost attribution</td></tr><tr><td>Executors</td><td>General reasoning, Codex, connectors, browser, desktop, documents, and human takeover</td></tr><tr><td>Safety and external action</td><td>Workspaces, network, short-lived credentials, preview, idempotency, and receipts</td></tr><tr><td>Memory and evolution</td><td>Memory write, retrieval, correction, forgetting, method candidates, canary, and rollback</td></tr><tr><td>Tests and evaluation</td><td>Unit, contract, integration, end-to-end, fault injection, security, soak, and real task sets</td></tr></tbody></table><p>Tasks, work units, and execution records stay separate. A task expresses the result the user wants; a work unit expresses a small authorized piece of work; an execution record expresses one real attempt. Only one effective executor advances a work unit at a time. Reassignment must prevent an old executor&#39;s late result from overwriting new state and must not duplicate external actions.</p><p>Fact records are append-only. Each record carries a version, relationships, and triggering reason. Task state, inbox, artifacts, and cost are projections. Upgrades remain compatible with old data, and replay cannot produce external effects. Large content lives in artifacts; records contain only references.</p><p>Tests and evaluations are different. A test is a deterministic pass/fail gate run on every commit. An evaluation is a statistical quality measurement that needs real task sets, baselines, and repeated comparison. Both matter, but they cannot be mixed into one check that only looks at an average score.</p><p>Tests cover at least nine areas: unit logic, executor and connector contracts, real-storage integration, browser vertical paths, fault injection, record replay, security denial paths, performance and soak, and real-task evaluation. Phase 1 can use simulated execution to exercise the interface and state first, then accept the MVP with real tasks.</p><p>Every small stage ships implementation, browser acceptance paths, failure paths, and regression tests together. Every bug fix has a regression test. Every record schema has migration and old-data compatibility tests. Every external action has idempotency and duplicate-delivery tests. Every new permission has denial-path tests. Every executor or connector has timeout, cancellation, and failure-classification tests.</p><p>Continuous integration has three tiers: unit, contract, integration, and simulated execution before merge, targeting ten minutes; daily fault injection, security, performance, external-service smoke tests, and soak tests; and full tests, migration, install, backup/restore, and phase exit acceptance before release.</p><p>Releases version data structures, executor protocols, and user-visible configuration. Upgrade makes a backup first, then verifies that old records, artifacts, memory, and authority remain readable; failure can roll back. Executor versions, method versions, and configuration are pinned. Real user data, credentials, and machine-specific paths never enter the test repository.</p>',18)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
